package com.ruoyi.warehouse.integrations;

import com.ruoyi.warehouse.support.WarehouseJson;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class WooCommerceReaderTest {
    static Map<String,Object> order(){return WarehouseJson.map("""
        {"id":9007199254740993,"number":"0000123","status":"processing","date_created_gmt":"2026-11-01T10:00:00","date_modified_gmt":"2026-11-01T12:00:00","date_paid_gmt":"2026-11-01T10:01:00","currency":"GBP","total":"12345678901234567890.125","refunds":[],"meta_data":[],"shipping":{"first_name":"Test","last_name":"Recipient","address_1":"1 Example Street","city":"Example","country":"GB","postcode":"TEST 1"},"billing":{"email":"synthetic@example.test"},"line_items":[{"id":31,"sku":"000012","name":"Synthetic physical item","quantity":2,"product_id":1,"variation_id":0,"total":"12.50","meta_data":[]}]}
        """);}
    Map<String,Object> window(){return new LinkedHashMap<>(Map.of("page",1,"since","2026-11-01T00:00:00Z","until","2026-11-02T00:00:00Z"));}
    @Test void exactIdentifiersMoneyAndLeadingZeroSkuRemainText(){var o=WooCommerceReader.normalize(order());assertEquals("9007199254740993",o.get("externalId"));assertEquals("12345678901234567890.125",o.get("total"));assertEquals("000012",WarehouseJson.maps(o.get("lines")).get(0).get("sku"));assertEquals("AWAITING_REVIEW",o.get("state"));assertEquals("ORDER_DETAILS_ONLY",o.get("verification"));assertFalse(o.containsKey("localOrder"));}
    @Test void unpaidRefundedAndPartiallyShippedSourcesAreHeld(){var raw=order();raw.put("date_paid_gmt",null);assertEquals("HELD",WooCommerceReader.normalize(raw).get("state"));raw=order();raw.put("refunds",List.of(Map.of("id",8)));assertTrue(((List<?>)WooCommerceReader.normalize(raw).get("reasons")).contains("REFUNDS_PRESENT"));raw=order();raw.put("meta_data",List.of(Map.of("key","_shipment_tracking_items","value",List.of("previous"))));assertEquals("HELD",WooCommerceReader.normalize(raw).get("state"));}
    @Test void cancelledAndCompletedOrdersNeverBecomeImportCandidates(){for(String status:List.of("cancelled","refunded","failed","completed")){var raw=order();raw.put("status",status);assertEquals(status.equals("completed")?"FULFILLED":"CANCELLED",WooCommerceReader.normalize(raw).get("state"));}}
    @Test void absentMetadataAndBundleComponentsRequireReview(){var raw=order();raw.remove("meta_data");assertEquals("HELD",WooCommerceReader.normalize(raw).get("state"));raw=order();WarehouseJson.maps(raw.get("line_items")).get(0).put("meta_data",List.of(Map.of("key","_bundled_by","value",10)));assertTrue(((List<?>)WooCommerceReader.normalize(raw).get("reasons")).contains("BUNDLE_REQUIRES_REVIEW"));}
    @Test void invalidQuantitiesDatesAndDuplicateLineIdentifiersFailTheWholePage(){var q=order();WarehouseJson.maps(q.get("line_items")).get(0).put("quantity",1.5);assertThrows(IntegrationFailure.class,()->WooCommerceReader.normalize(q));var d=order();d.put("date_modified_gmt","2026-02-30T00:00:00");assertThrows(IntegrationFailure.class,()->WooCommerceReader.normalize(d));var duplicate=order();duplicate.put("line_items",List.of(WarehouseJson.maps(duplicate.get("line_items")).get(0),WarehouseJson.maps(duplicate.get("line_items")).get(0)));assertThrows(IntegrationFailure.class,()->WooCommerceReader.normalize(duplicate));}
    @Test void fixedWindowUsesIdOrderingAndChecksTotalBeforeAdvancing(){var page=WooCommerceReader.fetch((path,params)->{assertEquals("/orders",path);assertEquals("id",params.get("orderby"));assertEquals("true",params.get("dates_are_gmt"));assertEquals("any",params.get("status"));return new IntegrationTransport.Response(200,List.of(order()),Map.of("x-wp-total","1","x-wp-totalpages","1"));},window());assertEquals("2026-11-02T00:00:00Z",page.next().get("completedUntil"));assertEquals(1,page.orders().size());}
    @Test void changingPageSetOrMissingPaginationEvidenceStopsProgress(){var w=window();w.put("total",2);assertEquals("REMOTE_PAGESET_CHANGED",assertThrows(IntegrationFailure.class,()->WooCommerceReader.fetch((p,q)->new IntegrationTransport.Response(200,List.of(order()),Map.of("x-wp-total","1","x-wp-totalpages","1")),w)).code());assertThrows(IntegrationFailure.class,()->WooCommerceReader.fetch((p,q)->new IntegrationTransport.Response(200,List.of(order()),Map.of()),window()));}
    @Test void providerErrorsNeverExposeRemoteErrorText(){for(int status:List.of(401,403,429,500)){var failure=assertThrows(IntegrationFailure.class,()->WooCommerceReader.fetch((p,q)->new IntegrationTransport.Response(status,Map.of("message","sensitive remote content"),Map.of()),window()));assertFalse(failure.getMessage().contains("sensitive"));}}
}
